from django.db import migrations, models

LIMITE = 100
TAMANHO_DO_NOME = 40


def _combinacoes(opcoes):
    """Opções antigas (Tamanho P/G, Cor Azul/Branca) -> combinações [('P, Azul', acréscimo somado), ...]."""
    combinacoes = [('', Decimal('0'))]
    for opcao in opcoes:
        combinacoes = [
            (f"{nome}, {valor['nome']}" if nome else valor['nome'], acrescimo + Decimal(valor['acrescimo']))
            for nome, acrescimo in combinacoes for valor in opcao['valores']
        ]
    return combinacoes[:LIMITE]


def opcoes_para_variacoes(apps, schema_editor):
    """Cada combinação das opções vira uma variação. O estoque, que era um só, fica todo na primeira: a loja
    distribui entre as variações na edição do produto. As vendas antigas ficam ligadas à variação delas."""
    Produto = apps.get_model('infrastructure', 'Produto')
    Variacao = apps.get_model('infrastructure', 'Variacao')
    ItemVenda = apps.get_model('infrastructure', 'ItemVenda')
    for produto in Produto.objects.all():
        if not produto.opcoes:
            continue
        variacoes = {}
        for nome, acrescimo in _combinacoes(produto.opcoes):
            nome = nome[:TAMANHO_DO_NOME]
            if nome.casefold() in variacoes:
                continue
            primeira = not variacoes and produto.controla_estoque
            variacoes[nome.casefold()] = Variacao.objects.create(
                produto=produto, nome=nome, acrescimo=acrescimo,
                quantidade_estoque=produto.quantidade_estoque if primeira else Decimal('0'),
            )
        for item in ItemVenda.objects.filter(produto=produto):
            nome = ", ".join(opcao['valor'] for opcao in item.opcoes)[:TAMANHO_DO_NOME]
            item.variacao = variacoes.get(nome.casefold())
            item.save(update_fields=['variacao'])


def variacoes_para_opcoes(apps, schema_editor):
    """Volta atrás: as variações viram uma opção "Variação" com um valor para cada (o estoque do produto não muda)."""
    Produto = apps.get_model('infrastructure', 'Produto')
    Variacao = apps.get_model('infrastructure', 'Variacao')
    for produto in Produto.objects.filter(pk__in=Variacao.objects.values('produto')):
        valores = [
            {'nome': variacao.nome, 'acrescimo': str(variacao.acrescimo)}
            for variacao in Variacao.objects.filter(produto=produto).order_by('pk')
        ]
        produto.opcoes = [{'nome': 'Variação', 'valores': valores}]
        produto.save(update_fields=['opcoes'])


